body.script:
(function () {
    var main = document.querySelector('main');
    var csrf = main.dataset.csrf;
    var maxBytes = parseInt(main.dataset.maxMb, 10) * 1024 * 1024;
    var msg = document.getElementById('msg');
    var busy = false;

    function show(kind, text) { msg.className = 'msg ' + kind; msg.textContent = text; }
    function setBusy(on) {
        busy = on;
        document.getElementById('uploadBtn').disabled = on;
        document.getElementById('driveBtn').disabled = on;
    }
    function done(data) {
        show('ok', 'Saved: ' + data.filename + ' (' + data.size + '). Close this tab and refresh the lesson to see it.');
        document.getElementById('now').textContent = 'Current video: ' + data.filename + ' · ' + data.size;
        document.getElementById('closeBtn').style.display = 'inline-block';
    }
    function failed(status, body) {
        if (status === 413) return show('err', 'That file is too big for the server to accept. Compress it, or ask whoever runs the server to raise the upload limit.');
        try { var data = JSON.parse(body); if (data.error) return show('err', data.error); } catch (e) {}
        show('err', 'Something went wrong (error ' + status + '). Check your connection and try again.');
    }

    document.getElementById('uploadBtn').addEventListener('click', function () {
        if (busy) return;
        var file = document.getElementById('file').files[0];
        if (!file) return show('err', 'Choose a video file first.');
        if (file.size > maxBytes) return show('err', 'That video is larger than ' + main.dataset.maxMb + ' MB. Compress it (720p MP4 works well) and try again.');
        var form = new FormData();
        form.append('csrf_token', csrf);
        form.append('video', file);
        var xhr = new XMLHttpRequest();
        var bar = document.getElementById('bar'), fill = document.getElementById('barFill'), status = document.getElementById('uploadStatus');
        bar.style.display = 'block';
        msg.className = 'msg';
        setBusy(true);
        xhr.upload.onprogress = function (e) {
            if (!e.lengthComputable) return;
            var pct = Math.round(e.loaded / e.total * 100);
            fill.style.width = pct + '%';
            status.textContent = pct < 100 ? 'Uploading… ' + pct + '%' : 'Saving on the server…';
        };
        xhr.onload = function () {
            setBusy(false);
            status.textContent = '';
            if (xhr.status === 200) { fill.style.width = '100%'; done(JSON.parse(xhr.responseText)); }
            else { bar.style.display = 'none'; failed(xhr.status, xhr.responseText); }
        };
        xhr.onerror = function () { setBusy(false); bar.style.display = 'none'; status.textContent = ''; show('err', 'The upload was interrupted. Check your connection and try again.'); };
        xhr.open('POST', main.dataset.uploadUrl);
        xhr.send(form);
    });

    document.getElementById('driveBtn').addEventListener('click', function () {
        if (busy) return;
        var link = document.getElementById('driveLink').value.trim();
        if (!link) return show('err', 'Paste a Google Drive link first.');
        var form = new FormData();
        form.append('csrf_token', csrf);
        form.append('drive_url', link);
        var status = document.getElementById('driveStatus');
        status.textContent = 'Copying from Google Drive… this can take a minute for a long video.';
        msg.className = 'msg';
        setBusy(true);
        fetch(main.dataset.driveUrl, { method: 'POST', body: form, credentials: 'same-origin' })
            .then(function (r) { return r.text().then(function (t) { return { status: r.status, body: t }; }); })
            .then(function (res) {
                setBusy(false);
                status.textContent = '';
                if (res.status === 200) done(JSON.parse(res.body)); else failed(res.status, res.body);
            })
            .catch(function () { setBusy(false); status.textContent = ''; show('err', 'Could not reach the server. Check your connection and try again.'); });
    });
})();
